/** 将报价 id 映射到收付款目标（receiptTargets 行 id），用于从报价卡片进入收款/结算时自动归属该报价。 */
function targetIdForQuote(projects:any[],quotes:any[],transactions:any[],quoteId:string):string{
 if(!quoteId)return '';
 const quote=quotes.find((value:any)=>value.id===quoteId);
 if(!quote)return '';
 const own=projects.find((value:any)=>value.id===quote.project);
 const root=own?.parent_id?projects.find((value:any)=>value.id===own.parent_id)||own:own;
 if(!root)return '';
 const targets=receiptTargets(root,projects,quotes,transactions).targets;
 if(quote.subproject_id)return targets.find((row:any)=>row.subprojectId===quote.subproject_id)?.id||'';
 const groupRow=targets.find((row:any)=>row.id===quote.project+':'+quote.id);
 if(groupRow)return groupRow.id;
 return targets.find((row:any)=>row.projectId===quote.project&&!row.subprojectId)?.id||'';
}
